@tailwind base;
@tailwind components;
@tailwind utilities;

/* إصلاح أيقونات التاريخ في الوضع الداكن - دعم جميع المتصفحات */
.dark input[type="datetime-local"]::-webkit-calendar-picker-indicator,
.dark input[type="date"]::-webkit-calendar-picker-indicator,
.dark input[type="time"]::-webkit-calendar-picker-indicator,
.dark input[type="datetime-local"]::-webkit-inner-spin-button,
.dark input[type="date"]::-webkit-inner-spin-button,
.dark input[type="time"]::-webkit-inner-spin-button {
  filter: invert(1) !important;
  cursor: pointer;
  opacity: 1 !important;
}

/* تحسين مظهر حقول التاريخ في الوضع الداكن */
.dark input[type="datetime-local"],
.dark input[type="date"],
.dark input[type="time"] {
  color-scheme: dark;
