  --shadow-lg: 0px 10px 20px -4px hsl(220 13% 20% / 0.12), 0px 4px 8px -4px hsl(220 13% 20% / 0.08);
  --shadow-xl: 0px 20px 30px -6px hsl(220 13% 20% / 0.15), 0px 8px 12px -6px hsl(220 13% 20% / 0.10);
  --shadow-2xl: 0px 30px 50px -8px hsl(220 13% 20% / 0.20);

  /* Computed borders */
  --primary-border: hsl(var(--primary));
  --primary-border: hsl(from hsl(var(--primary)) h s calc(l + var(--opaque-button-border-intensity)) / alpha);

  --secondary-border: hsl(var(--secondary));
