@layer base {
  * {
    @apply border-border;
  }

  body {
    @apply font-sans antialiased bg-background text-foreground;
  }
}

/**
 * ===== Elevation System =====
 * Modern hover and active states with automatic contrast
 */
@layer utilities {

  /* Hide search cancel button */
  input[type="search"]::-webkit-search-cancel-button {
    @apply hidden;
  }

  /* Placeholder for contentEditable */
  [contenteditable][data-placeholder]:empty::before {
    content: attr(data-placeholder);
    color: hsl(var(--muted-foreground));
    pointer-events: none;
  }

  /* Elevation escape hatches */
  .no-default-hover-elevate {}
  .no-default-active-elevate {}

  /* Toggle elevation backgrounds */
  .toggle-elevate::before,
  .toggle-elevate-2::before {
    content: "";
    pointer-events: none;
    position: absolute;
    inset: 0px;
    border-radius: inherit;
    z-index: -1;
  }

  .toggle-elevate.toggle-elevated::before {
    background-color: var(--elevate-2);
  }

  .border.toggle-elevate::before {
    inset: -1px;
  }

  /* Hover and active elevation */
  .hover-elevate:not(.no-default-hover-elevate),
  .active-elevate:not(.no-default-active-elevate),
  .hover-elevate-2:not(.no-default-hover-elevate),
  .active-elevate-2:not(.no-default-active-elevate) {
    position: relative;
    z-index: 0;
  }

  .hover-elevate:not(.no-default-hover-elevate)::after,
  .active-elevate:not(.no-default-active-elevate)::after,
  .hover-elevate-2:not(.no-default-hover-elevate)::after,
  .active-elevate-2:not(.no-default-active-elevate)::after {
    content: "";
    pointer-events: none;
    position: absolute;
    inset: 0px;
    border-radius: inherit;
    z-index: 999;
  }

  .hover-elevate:hover:not(.no-default-hover-elevate)::after,
  .active-elevate:active:not(.no-default-active-elevate)::after {
    background-color: var(--elevate-1);
  }

  .hover-elevate-2:hover:not(.no-default-hover-elevate)::after,
  .active-elevate-2:active:not(.no-default-active-elevate)::after {
    background-color: var(--elevate-2);
  }

  .border.hover-elevate:not(.no-hover-interaction-elevate)::after,
  .border.active-elevate:not(.no-active-interaction-elevate)::after,
  .border.hover-elevate-2:not(.no-hover-interaction-elevate)::after,
  .border.active-elevate-2:not(.no-active-interaction-elevate)::after {
    inset: -1px;
  }

  /* ===== Modern Gradient Utilities ===== */

  /* Blue Gradient */
  .bg-gradient-blue {
    @apply bg-gradient-to-br from-blue-50 to-blue-100;
  }
  .dark .bg-gradient-blue {
    @apply from-blue-950/50 to-blue-900/50;
  }

  /* Purple Gradient */
  .bg-gradient-purple {
    @apply bg-gradient-to-br from-purple-50 to-purple-100;
  }
  .dark .bg-gradient-purple {
    @apply from-purple-950/50 to-purple-900/50;
  }

  /* Turquoise Gradient */
  .bg-gradient-turquoise {
    @apply bg-gradient-to-br from-cyan-50 to-cyan-100;
  }
  .dark .bg-gradient-turquoise {
    @apply from-cyan-950/50 to-cyan-900/50;
  }

  /* Multi-color Gradient */
  .bg-gradient-multi {
    @apply bg-gradient-to-br from-blue-50 via-purple-50 to-cyan-50;
  }
  .dark .bg-gradient-multi {
    @apply from-blue-950/50 via-purple-950/50 to-cyan-950/50;
  }

  /* ===== Custom Scrollbar Styles (Beautiful Sidebar Scroll) ===== */
  /* تنسيقات سكرول جميلة للقائمة الجانبية مع دعم الوضع الداكن */

  .sidebar-scroll::-webkit-scrollbar {
    width: 8px;
  }

  .sidebar-scroll::-webkit-scrollbar-track {
    background: rgba(255, 255, 255, 0.05);
    border-radius: 10px;
    margin: 8px 0;
  }

  .sidebar-scroll::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, rgba(96, 165, 250, 0.6), rgba(147, 51, 234, 0.6));
    border-radius: 10px;
    border: 2px solid transparent;
    background-clip: padding-box;
    transition: all 0.3s ease;
  }

  .sidebar-scroll::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(180deg, rgba(96, 165, 250, 0.9), rgba(147, 51, 234, 0.9));
    border: 1px solid rgba(255, 255, 255, 0.2);
    box-shadow: 0 0 8px rgba(96, 165, 250, 0.5);
  }

  /* Dark mode scrollbar - elegant gray gradient */
  .dark .sidebar-scroll::-webkit-scrollbar-track {
    background: rgba(0, 0, 0, 0.2);
  }

  .dark .sidebar-scroll::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, rgba(75, 85, 99, 0.7), rgba(55, 65, 81, 0.7));
  }

  .dark .sidebar-scroll::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(180deg, rgba(107, 114, 128, 0.95), rgba(75, 85, 99, 0.95));
    border: 1px solid rgba(255, 255, 255, 0.15);
    box-shadow: 0 0 8px rgba(107, 114, 128, 0.5);
  }

  /* Firefox scrollbar support */
  .sidebar-scroll {
    scrollbar-width: thin;
    scrollbar-color: rgba(96, 165, 250, 0.6) rgba(255, 255, 255, 0.05);
  }

  .dark .sidebar-scroll {
    scrollbar-color: rgba(75, 85, 99, 0.7) rgba(0, 0, 0, 0.2);
  }
}

/* ===== Mobile Responsive Improvements ===== */
@media (max-width: 768px) {
  /* تحسين الجداول على الموبايل */
  table {
    font-size: 0.875rem;
  }

  table th,
  table td {
    padding: 0.5rem !important;
  }

  /* إضافة مؤشر للتمرير الأفقي */
  .overflow-x-auto::after {
    content: '';
    position: absolute;
    right: 0;
    top: 0;
    bottom: 0;
    width: 30px;
    background: linear-gradient(to left, rgba(0,0,0,0.1), transparent);
    pointer-events: none;
    opacity: 0;
    transition: opacity 0.3s;
  }

  .dark .overflow-x-auto::after {
    background: linear-gradient(to left, rgba(255,255,255,0.1), transparent);
  }

  /* تحسين الأزرار على الموبايل */
  button {
    min-height: 44px;
    min-width: 44px;
  }

  /* تحسين حجم الـ Modal على الموبايل */
  .modal-content {
    max-width: 95vw !important;
    max-height: 90vh;
    overflow-y: auto;
  }

  /* تحسين الكروت (Cards) على الموبايل */
  .p-6 {
    padding: 1rem !important;
  }

  .p-4 {
    padding: 0.75rem !important;
  }

  .p-3 {
    padding: 0.5rem !important;
  }

  /* تحسين الفلاتر والنماذج */
  .space-y-6 > * + * {
    margin-top: 1rem !important;
  }

  .space-y-5 > * + * {
    margin-top: 0.875rem !important;
  }

  .space-y-4 > * + * {
    margin-top: 0.75rem !important;
  }

  /* تحسين كروت الفئات والإحصائيات */
  .min-w-\[120px\] {
    min-width: 100px !important;
  }

  .min-w-\[150px\] {
    min-width: 120px !important;
  }

  /* تقليل حجم النصوص الكبيرة على الموبايل */
  .text-4xl {
    font-size: 1.875rem !important;
  }

  .text-3xl {
    font-size: 1.5rem !important;
  }

  .text-2xl {
    font-size: 1.25rem !important;
  }

  .text-xl {
    font-size: 1.125rem !important;
  }

  /* تحسين Grid على الموبايل */
  .grid {
    gap: 0.75rem !important;
  }

  .gap-4 {
    gap: 0.75rem !important;
  }

  .gap-3 {
    gap: 0.5rem !important;
  }

  /* تحسين Flex Wrap */
  .flex-wrap {
    gap: 0.5rem !important;
  }
}

/* ===== Print Styles ===== */
@media print {
  @page {
    margin: 10mm;
  }

  /* إخفاء العناصر التي لا يجب طباعتها */
  .print\:hidden {
    display: none !important;
  }

  /* إظهار فقط المحتوى المراد طباعته */
  body {
    background: white !important;
  }

  /* أنماط طباعة التقرير الجماعي */
  .report-table {
    width: 100%;
    border-collapse: collapse;
    page-break-inside: auto;
  }

  .report-table tr {
    page-break-inside: avoid;
    page-break-after: auto;
  }

  .report-table th,
  .report-table td {
    border: 1px solid #000 !important;
    padding: 6px;
    font-size: 8pt;
    text-align: right;
    color: #000 !important;
  }

  .report-table th {
    background-color: #f2f2f2 !important;
    font-weight: bold;
  }

  .report-header {
    border-bottom: 2px solid #333;
    padding-bottom: 10px;
    margin-bottom: 20px;
    text-align: center;
    color: #000 !important;
  }

  /* أنماط طباعة قسيمة الراتب (80mm) */
  @page {
    size: 80mm auto;
    margin: 5mm;
  }

  /* طباعة الباركود */
  .barcode-sticker {
    width: 50mm;
    height: 30mm;
    background: white;
    color: #000 !important;
  }
}

